import{z as n,x as i,o,c as d,q as t,j as l,D as B,d as E,s as A,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"大对象存储","description":"","frontmatter":{"title":"大对象存储","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blob-storage.md","filePath":"cs/blob-storage.md","lastUpdated":1791063341000}'),p={name:"cs/blob-storage.md"};function L(C,a,O,m,c,f){const r=i("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="大对象存储" tabindex="-1">大对象存储 <a class="header-anchor" href="#大对象存储" aria-label="Permalink to &quot;大对象存储&quot;">​</a></h1><div class="epigraph"><p>大对象不进普通行槽：流式读写、单独 WAL 策略、可选外置文件，避免一次把缓冲池打成一张图片。</p><footer>—— 据 SQL BLOB/CLOB；Stonebraker 等对大对象；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/varlen-overflow">上一课</a>把中等变长放进溢出链。本课不跟转发 RID。缺口是 MB–GB 级值：若当超长 VARCHAR，VACUUM、复制、统计、一次 <code>SELECT *</code> 都会灾难。大对象（LOB）是另一存储主键：oid 在行上，字节在侧表或文件系统，API 是分段读写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>事务：LOB 写入要原子可见，崩溃要回滚未提交字节。若外置文件不进 WAL，就要另做强制与垃圾回收。缺口是<strong>与行同一 ACID 还是最终一致外链</strong>。应用把图片 URL 放进对象存储、库内只留键，是常见切分——那是应用设计，库仍可能提供内置 LOB。</p><p><span class="marginnote">术语翻译：BLOB 就是「二进制大对象」——图片、音频的原始字节；CLOB 是字符大对象——整本书的文本。数据库在行上只放一个引用号，真正的字节躺在侧表段页或文件系统里，要用专门 API 分段取。</span></p><p>复制：物理复制会把 LOB 页也传；逻辑复制可能跳过或切片。CDC 后课。查询优化：不要把 LOB 列拖进哈希表当连接键。</p><p><span class="marginnote">SQL 标准 BLOB/CLOB。PostgreSQL large object 与 TOAST 阈值分工。本课不把对象存储网关当数据库内核必做，但点名外置是合法边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行内存 LOB 定位符。读：<code>read(offset, len)</code> 填缓冲，不一次性物化。写：追加或覆盖段，日志按段。GC：删除行后回收 LOB 页，与 MVCC 可见性对齐——未结束快照仍可能读旧字节。</p><p>索引：通常不直接索全文，可对校验或元数据列索引；全文倒排对 CLOB 要分词管道。</p>',11)),(o(),l(s,null,{default:B(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROW%5B%22%E8%A1%8C%E4%B8%8A%20LOB%20%E5%BC%95%E7%94%A8%22%5D%20--%3E%20SEG%5B%22%E6%AE%B5%E9%A1%B5%E6%88%96%E4%BE%A7%E8%A1%A8%22%5D%0A%20%20SEG%20--%3E%20API%5B%22%E6%B5%81%E5%BC%8F%E8%AF%BB%20%2F%20%E5%86%99%22%5D%0A%20%20API%20--%3E%20WAL%5B%22%E6%8C%89%E6%AE%B5%E6%97%A5%E5%BF%97%22%5D%0A%20%20ROW%20--%3E%20EXT%5B%22%E6%88%96%E5%A4%96%E7%BD%AE%E5%AF%B9%E8%B1%A1%E9%94%AE%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：行内的 LOB 定位符像借书证上的一行「第 7 排书架，编号 1234」，而不是把整本书钉在卡上。行永远轻巧地移动、复制、索引；真正的重物留在书架上，要用时凭号去取一段。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"缓冲池：LOB 段用一次性访问模式，替换应像扫描。pin 泄漏一张 1GB 对象会冻死池。压缩：段级压缩，随机偏移要可寻址或放弃跨段解压。",-1)),a[6]||(a[6]=e("p",null,"安全：权限在行级还是 LOB oid 级，漏洞常出在「知道 oid 就能读」。行级安全后课。",-1)),a[7]||(a[7]=e("p",null,"一次整取与一次分段读的差别，值得画出来。",-1)),(o(),l(s,null,{default:B(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E8%A6%81%E5%9B%BE%E9%87%8C%E7%9A%84%2064%20KB%22%5D%20--%3E%20A%5B%22SELECT%20*%EF%BC%9A%E7%89%A9%E5%8C%96%E6%95%B4%E4%B8%AA%201%20GB%22%5D%0A%20%20A%20--%3E%20BP%5B%22%E7%BC%93%E5%86%B2%E6%B1%A0%E8%A2%AB%20LOB%20%E6%AE%B5%E5%8D%A0%E6%BB%A1%22%5D%0A%20%20BP%20--%3E%20COLD%5B%22%E7%83%AD%E9%A1%B5%E8%A2%AB%E6%8C%A4%E8%B5%B0%EF%BC%8C%E5%85%A8%E5%BA%93%E5%8F%98%E6%85%A2%22%5D%0A%20%20APP%20--%3E%20B%5B%22read(offset%2C%20len)%EF%BC%9A%E5%8F%AA%E5%8F%96%E8%AF%A5%E6%AE%B5%22%5D%0A%20%20B%20--%3E%20OK%5B%22%E7%BC%93%E5%86%B2%E6%B1%A0%E5%8F%AA%E7%BB%8F%E6%89%8B%2064%20KB%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">常见误区：以为 <code>SELECT *</code> 顶多多花点网络流量。对 LOB 表它是灾难：1 GB 的字节会被物化进缓冲池并 pin 住，热数据页全被挤走，一张图片冻死整个库。数字实例：流式 <code>read(0, 65536)</code> 一次只经手 64 KB，两者差一万多倍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲表分区键如何包含 LOB。也不把向量嵌入当 BLOB 教程——向量库后课有自己的 ANN 文件。透明加密可盖 LOB 段。</p><p>后课默认：大值走 LOB 或外置，行上只留引用。表分区：水平切行集合，控制扫描与维护窗口。</p><p>一次 <code>SELECT *</code> 拉出所有 LOB 是接口设计错误，不是优化器无能。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LOB 流式分段，行上存引用；WAL/GC 必须覆盖段。</li><li>外置对象存储把一致性边界外移。</li><li>表分区下一课：按键水平切表。</li><li>出处：SQL LOB；Ramakrishnan and Gehrke；TOAST/large object 实践。</li></ul>',7))])}const u=n(p,[["render",L]]);export{h as __pageData,u as default};
